function refClassify(m){if(m>=0&&m<50)return'standby';if(m>=50&&m<200)return'idle';if(m>=200&&m<600)return'active';if(m>=600&&m<900)return'loaded';if(m>=900)return'critical';return'negative'}
function refAlerts(parsed){const a=[];for(const r of parsed){if(r.m>=900)a.push(r.channel+':critical');else if(r.m<0)a.push(r.channel+':negative');else if(r.m>=600&&r.m<900)a.push(r.channel+':loaded')}return a}

function refProcess(raw){
  if(typeof raw!=='object'||raw===null)return{ok:false,error:'malformed batch'};
  if(!Array.isArray(raw.readings))return{ok:false,error:'missing readings'};
  if(raw.readings.length===0)return{ok:false,error:'empty batch'};
  if(raw.readings.length>500)return{ok:false,error:'batch too large'};
  const parsed=[];
  for(let i=0;i<raw.readings.length;i++){
    const e=raw.readings[i];
    if(typeof e!=='object'||e===null)return{ok:false,error:'reading '+i+': malformed'};
    if(typeof e.channel!=='string'||e.channel.length===0)return{ok:false,error:'reading '+i+': bad channel'};
    if(['uV','mV','V'].indexOf(e.unit)<0)return{ok:false,error:'reading '+i+': bad unit'};
    if(!Number.isInteger(e.value))return{ok:false,error:'reading '+i+': bad value'};
    if(!Number.isInteger(e.at)||e.at<0)return{ok:false,error:'reading '+i+': bad timestamp'};
    let mv; if(e.unit==='V')mv=e.value*1000; else if(e.unit==='uV')mv=Math.trunc(e.value/1000); else mv=e.value;
    parsed.push({channel:e.channel,millivolts:mv,at:e.at});
  }
  const labels=parsed.map(r=>refClassify(r.millivolts));
  const alerts=refAlerts(parsed);
  const channels={};
  for(let i=0;i<parsed.length;i++){const r=parsed[i];const ex=channels[r.channel];
    if(ex===undefined){channels[r.channel]={count:1,min:r.millivolts,max:r.millivolts,worst:labels[i]};continue}
    ex.count++;if(r.millivolts<ex.min)ex.min=r.millivolts;if(r.millivolts>ex.max)ex.max=r.millivolts;
    const rank=l=>{if(l==='negative')return 5;if(l==='critical')return 4;if(l==='loaded')return 3;if(l==='active')return 2;if(l==='idle')return 1;return 0};
    if(rank(labels[i])>rank(ex.worst))ex.worst=labels[i];
  }
  let worst='standby';for(const l of labels){const rank=l=>{if(l==='negative')return 5;if(l==='critical')return 4;if(l==='loaded')return 3;if(l==='active')return 2;if(l==='idle')return 1;return 0};if(rank(l)>rank(worst))worst=l}
  return {ok:true,readings:parsed.length,labels,channels,alerts,report:'readings='+parsed.length+';channels='+Object.keys(channels).length+';alerts='+alerts.length+';worst='+worst};
}

const cases=[];
const units=['uV','mV','V'];
function mkReading(i){return {channel:'ch'+i, unit:units[i%3], value:(i*137)%2000 - (i%5===0?500:0), at:i}}
// diverse valid batch
const valid = {readings:[]};
