cases.push(valid);

// invalid batch cases
cases.push(null, {}, {readings:[]}, {readings:[1,2,3]}, {readings:[{channel:'',unit:'mV',value:1,at:0}]},
  {readings:[{channel:'c',unit:'X',value:1,at:0}]}, {readings:[{channel:'c',unit:'V',value:'x',at:0}]},
  {readings:[{channel:'c',unit:'V',value:1,at:-1}]}, {readings:new Array(501).fill({channel:'c',unit:'mV',value:1,at:0})},
  {readings:[{channel:'c',unit:'V',value:-2,at:0},{channel:'c',unit:'uV',value:1000000,at:1}]});

const vals=[-100,-1,0,49,50,199,200,599,600,899,900,1200];
for(const v of vals){
  const r={readings:[{channel:'neg',unit:'mV',value:v,at:0}]};
  // value must be integer
  cases.push(r);
}

let mismatches=0;
for(const c of cases){
  const a=JSON.stringify(t.processBatch(c));
  const b=JSON.stringify(refProcess(c));
  if(a!==b){mismatches++;console.log('MISMATCH',JSON.stringify(c),'\n  new:',a,'\n  ref:',b)}
}
console.log('Cases tested:',cases.length,'Mismatches:',mismatches);
